import { DEFAULT_TEXT, loadText, saveText } from "./storage.js";

function getStorage() {
  try {
    return window.localStorage;
  } catch (error) {
    console.error("hello-world: localStorage is unavailable; edits will not persist", error);
    return null;
  }
}

function insertPlainText(text) {
  const selection = window.getSelection();
  if (!selection || selection.rangeCount === 0) return;
  const range = selection.getRangeAt(0);
  range.deleteContents();
  const node = document.createTextNode(text.replace(/[\r\n]+/g, " "));
  range.insertNode(node);
  range.setStartAfter(node);
  range.collapse(true);
  selection.removeAllRanges();
  selection.addRange(range);
}

function normalise(headline) {
  // Strip any stray elements (e.g. <br>) a browser may have inserted.
  if (headline.childElementCount > 0) {
    headline.textContent = headline.textContent;
  }
}

function start() {
  const headline = document.getElementById("headline");
  const storage = getStorage();

  headline.textContent = storage ? loadText(storage) : DEFAULT_TEXT;

  headline.addEventListener("input", () => {
    normalise(headline);
    if (storage) saveText(storage, headline.textContent);
  });

  headline.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      headline.blur();
    }
  });

  headline.addEventListener("paste", (event) => {
    event.preventDefault();
    insertPlainText(event.clipboardData?.getData("text/plain") ?? "");
    headline.dispatchEvent(new Event("input", { bubbles: true }));
  });

  headline.addEventListener("blur", () => {
    if (headline.textContent.trim() === "") {
      headline.textContent = DEFAULT_TEXT;
    }
  });
}

start();

export const DEFAULT_TEXT = "hello world";
export const STORAGE_KEY = "hello-world:text";

export function loadText(storage) {
  try {
    const value = storage.getItem(STORAGE_KEY);
    return value === null ? DEFAULT_TEXT : value;
  } catch (error) {
    console.error(`hello-world: failed to load text from storage key "${STORAGE_KEY}"`, error);
    return DEFAULT_TEXT;
  }
}

export function saveText(storage, text) {
  const isBlank = text.trim() === "";
  try {
    if (isBlank) {
      storage.removeItem(STORAGE_KEY);
    } else {
      storage.setItem(STORAGE_KEY, text);
    }
  } catch (error) {
    const operation = isBlank ? "remove" : "save";
    console.error(`hello-world: failed to ${operation} text at storage key "${STORAGE_KEY}"`, error);
  }
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { DEFAULT_TEXT, STORAGE_KEY, loadText, saveText } from "../src/storage.js";

function createFakeStorage() {
  const items = new Map();
  return {
    items,
    getItem: (key) => (items.has(key) ? items.get(key) : null),
    setItem: (key, value) => items.set(key, String(value)),
    removeItem: (key) => items.delete(key),
  };
}

function createThrowingStorage() {
  const fail = () => {
    throw new Error("storage blocked");
  };
  return { getItem: fail, setItem: fail, removeItem: fail };
}

test("load with an empty store returns the default text", () => {
  assert.equal(DEFAULT_TEXT, "hello world");
  assert.equal(loadText(createFakeStorage()), "hello world");
});

test("save then load round-trips the text under hello-world:text", () => {
  const storage = createFakeStorage();
  saveText(storage, "  hi there ");
  assert.equal(STORAGE_KEY, "hello-world:text");
  assert.equal(storage.items.get("hello-world:text"), "  hi there ");
  assert.equal(loadText(storage), "  hi there ");
});

test("saving whitespace-only text removes the key", () => {
  const storage = createFakeStorage();
  saveText(storage, "edited");
  saveText(storage, " \t ");
  assert.equal(storage.items.has(STORAGE_KEY), false);
  assert.equal(loadText(storage), DEFAULT_TEXT);
});

test("a read that throws returns the default and logs an error", (t) => {
  const errorMock = t.mock.method(console, "error", () => {});
  assert.equal(loadText(createThrowingStorage()), DEFAULT_TEXT);
  assert.equal(errorMock.mock.callCount(), 1);
  assert.match(errorMock.mock.calls[0].arguments[0], /failed to load/);
});

test("a write that throws does not throw and logs an error", (t) => {
  const errorMock = t.mock.method(console, "error", () => {});
  assert.doesNotThrow(() => saveText(createThrowingStorage(), "new text"));
  assert.doesNotThrow(() => saveText(createThrowingStorage(), ""));
  assert.equal(errorMock.mock.callCount(), 2);
  assert.match(errorMock.mock.calls[0].arguments[0], /failed to save/);
  assert.match(errorMock.mock.calls[1].arguments[0], /failed to remove/);
});

:root {
  --bg: #07060f;
  --ink: #f5f3ff;
  --c1: #7c3aed;
  --c2: #06b6d4;
  --c3: #f472b6;
  --c4: #facc15;
  color-scheme: dark;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

body {
  min-height: 100vh;
  min-height: 100dvh;
  overflow: hidden;
  background: radial-gradient(ellipse at 50% 120%, #1e1b4b 0%, var(--bg) 60%);
  color: var(--ink);
  font-family: ui-rounded, "SF Pro Rounded", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

/* Aurora background: three blurred blobs drifting on the GPU (transform only). */
.aurora {
  position: fixed;
  inset: 0;
  overflow: hidden;
  filter: blur(70px) saturate(140%);
  opacity: 0.75;
}

.blob {
  position: absolute;
  width: 60vmax;
  height: 60vmax;
  border-radius: 50%;
  mix-blend-mode: screen;
  will-change: transform;
}

.blob--1 {
  top: -20vmax;
  left: -15vmax;
  background: radial-gradient(circle, var(--c1) 0%, transparent 65%);
  animation: drift-1 22s ease-in-out infinite alternate;
}

.blob--2 {
  bottom: -25vmax;
  right: -20vmax;
  background: radial-gradient(circle, var(--c2) 0%, transparent 65%);
  animation: drift-2 26s ease-in-out infinite alternate;
}

.blob--3 {
  top: 30%;
  left: 35%;
  width: 45vmax;
  height: 45vmax;
  background: radial-gradient(circle, var(--c3) 0%, transparent 65%);
  animation: drift-3 30s ease-in-out infinite alternate;
}

@keyframes drift-1 {
  to { transform: translate(25vw, 20vh) scale(1.2); }
}

@keyframes drift-2 {
  to { transform: translate(-30vw, -15vh) scale(0.9); }
}

@keyframes drift-3 {
  to { transform: translate(-25vw, 10vh) scale(1.3); }
}

/* Subtle vignette for depth and text contrast. */
body::after {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background: radial-gradient(ellipse at center, transparent 40%, rgb(0 0 0 / 0.55) 100%);
}

.stage {
  position: relative;
  z-index: 1;
  min-height: 100vh;
  min-height: 100dvh;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 1.5rem;
  padding: 1.5rem;
  text-align: center;
}

.headline {
  margin: 0;
  max-width: 92vw;
  padding: 0.1em 0.35em 0.15em;
  border-radius: 0.3em;
  font-size: clamp(3rem, 14vw, 11rem);
  font-weight: 800;
  line-height: 1.05;
  letter-spacing: -0.04em;
  overflow-wrap: anywhere;
  white-space: pre-wrap;
  background: linear-gradient(100deg, #fff 0%, #c4b5fd 25%, #67e8f9 50%, #f9a8d4 75%, #fff 100%);
  background-size: 200% auto;
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: var(--ink);
  caret-color: var(--c4);
  filter: drop-shadow(0 0 24px rgb(167 139 250 / 0.45));
  cursor: text;
  outline: none;
  transition: box-shadow 0.3s ease, background-color 0.3s ease;
  animation: shimmer 8s linear infinite;
}

.headline:hover {
  background-color: rgb(255 255 255 / 0.03);
}

.headline:focus-visible,
.headline:focus {
  background-color: rgb(255 255 255 / 0.06);
  box-shadow:
    0 0 0 2px rgb(250 204 21 / 0.85),
    0 0 40px 6px rgb(124 58 237 / 0.45);
}

@keyframes shimmer {
  to { background-position: -200% center; }
}

.hint {
  margin: 0;
  padding: 0.5rem 1rem;
  border: 1px solid rgb(255 255 255 / 0.18);
  border-radius: 999px;
  background: rgb(15 12 35 / 0.45);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  color: rgb(245 243 255 / 0.85);
  font-size: clamp(0.8rem, 2.8vw, 1rem);
  letter-spacing: 0.04em;
  transition: opacity 0.4s ease, transform 0.4s ease;
}

.headline:focus + .hint {
  opacity: 0;
  transform: translateY(6px);
}

@media (prefers-reduced-motion: reduce) {
  .blob,
  .headline {
    animation: none;
  }

  .headline,
  .hint {
    transition: none;
  }
}
